input.new_string:
import { after } from 'next/server';

async function logPageView() {
  // Replace with a real analytics service call, e.g.:
  // await fetch('https://analytics.example.com/events', { method: 'POST', ... })
  console.log('[analytics] page view logged at', new Date().toISOString());
}

export default function Home() {
  // Schedules logPageView to run after the response is sent.
  // The client receives the HTML immediately; logging happens in the background.
  after(logPageView);

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting! Your page view is being recorded in the background.</p>
    </main>
  );
}

